using UnityEngine;
using UnityEngine.InputSystem;

// Reads the project-wide actions (Edit > Project Settings > Input System Package).
// Other scripts only use the properties below.
public class PlayerInputReader : MonoBehaviour
{
    private InputAction moveAction;
    private InputAction lookAction;
    private InputAction jumpAction;
    private InputAction sprintAction;
    private InputAction attackAction;
    private InputAction interactAction;

    public Vector2 Move { get; private set; }
    public Vector2 Look { get; private set; }
    public bool JumpPressed { get; private set; }
    public bool JumpHeld { get; private set; }
    public bool SprintHeld { get; private set; }
    public bool AttackPressed { get; private set; }
    public bool InteractPressed { get; private set; }

    private void Awake()
    {
        moveAction = InputSystem.actions.FindAction("Move");
        lookAction = InputSystem.actions.FindAction("Look");
        jumpAction = InputSystem.actions.FindAction("Jump");
        sprintAction = InputSystem.actions.FindAction("Sprint");
        attackAction = InputSystem.actions.FindAction("Attack");
        interactAction = InputSystem.actions.FindAction("Interact");
    }

    private void Update()
    {
        Move = moveAction != null ? moveAction.ReadValue<Vector2>() : Vector2.zero;
        Look = lookAction != null ? lookAction.ReadValue<Vector2>() : Vector2.zero;
        JumpPressed = jumpAction != null && jumpAction.WasPressedThisFrame();
        JumpHeld = jumpAction != null && jumpAction.IsPressed();
        SprintHeld = sprintAction != null && sprintAction.IsPressed();
        AttackPressed = attackAction != null && attackAction.WasPressedThisFrame();
        InteractPressed = interactAction != null && interactAction.WasPressedThisFrame();
    }
}

using UnityEngine;

// Side view: run, jump, variable jump height, coyote time and jump buffer.
[RequireComponent(typeof(Rigidbody2D), typeof(PlayerInputReader))]
public class PlatformerController2D : MonoBehaviour
{
    [Header("Laufen")]
    [SerializeField] private float moveSpeed = 8f;
    [SerializeField] private float acceleration = 60f;

    [Header("Springen")]
    [SerializeField] private float jumpVelocity = 14f;
    [SerializeField] private float coyoteTime = 0.1f;   // seconds after leaving the edge
    [SerializeField] private float jumpBuffer = 0.12f;  // seconds before landing
    [SerializeField] private float jumpCutMultiplier = 0.5f; // button released early = smaller jump

    [Header("Boden")]
    [SerializeField] private Transform groundCheck;
    [SerializeField] private float groundRadius = 0.15f;
    [SerializeField] private LayerMask groundLayer;

    private Rigidbody2D body;
    private PlayerInputReader input;
    private SpriteRenderer sprite;
    private float lastGroundedTime = -10f;
    private float lastJumpPressedTime = -10f;

    public bool IsGrounded { get; private set; }

    private void Awake()
    {
        body = GetComponent<Rigidbody2D>();
        input = GetComponent<PlayerInputReader>();
        sprite = GetComponentInChildren<SpriteRenderer>();
    }

    private void Update()
    {
        IsGrounded = Physics2D.OverlapCircle(groundCheck.position, groundRadius, groundLayer);
        if (IsGrounded) lastGroundedTime = Time.time;
        if (input.JumpPressed) lastJumpPressedTime = Time.time;

        bool canJump = Time.time - lastGroundedTime <= coyoteTime;
        bool wantsJump = Time.time - lastJumpPressedTime <= jumpBuffer;
        if (canJump && wantsJump)
        {
            body.linearVelocity = new Vector2(body.linearVelocity.x, jumpVelocity);
            lastJumpPressedTime = -10f;
            lastGroundedTime = -10f;
        }

        // Button released early: cut the jump short
        if (!input.JumpHeld && body.linearVelocity.y > 0f)
        {
            body.linearVelocity = new Vector2(body.linearVelocity.x, body.linearVelocity.y * jumpCutMultiplier);
        }

        if (sprite != null && Mathf.Abs(input.Move.x) > 0.01f) sprite.flipX = input.Move.x < 0f;
    }

    private void FixedUpdate()
    {
        float target = input.Move.x * moveSpeed;
        float x = Mathf.MoveTowards(body.linearVelocity.x, target, acceleration * Time.fixedDeltaTime);
        body.linearVelocity = new Vector2(x, body.linearVelocity.y);
    }

    private void OnDrawGizmosSelected()
    {
        if (groundCheck == null) return;
        Gizmos.color = Color.yellow;
        Gizmos.DrawWireSphere(groundCheck.position, groundRadius);
    }
}

using UnityEngine;

// Walks back and forth, turns around at walls and ledges.
[RequireComponent(typeof(Rigidbody2D))]
public class Patrol2D : MonoBehaviour
{
    [SerializeField] private float speed = 2f;
    [SerializeField] private Transform wallCheck;
    [SerializeField] private Transform ledgeCheck;
    [SerializeField] private LayerMask groundLayer;

    private Rigidbody2D body;
    private int direction = 1;

    private void Awake()
    {
        body = GetComponent<Rigidbody2D>();
    }

    private void FixedUpdate()
    {
        bool wallAhead = Physics2D.OverlapCircle(wallCheck.position, 0.1f, groundLayer);
        bool groundAhead = Physics2D.OverlapCircle(ledgeCheck.position, 0.1f, groundLayer);
        if (wallAhead || !groundAhead) Flip();
        body.linearVelocity = new Vector2(direction * speed, body.linearVelocity.y);
    }

    private void Flip()
    {
        direction = -direction;
        Vector3 scale = transform.localScale;
        scale.x = Mathf.Abs(scale.x) * direction;
        transform.localScale = scale; // also mirrors the check points
    }
}

using UnityEngine;
using UnityEngine.Events;

// Health for the player or enemies. Other scripts call TakeDamage.
public class Health : MonoBehaviour
{
    [SerializeField] private int maxHealth = 5;
    public UnityEvent<int> onHealthChanged; // connect in the Inspector, e.g. to the health bar
    public UnityEvent onDied;

    public int Current { get; private set; }
    public int Max => maxHealth;

    private void Awake()
    {
        Current = maxHealth;
    }

    public void TakeDamage(int amount)
    {
        if (Current <= 0) return;
        Current = Mathf.Max(0, Current - amount);
        onHealthChanged?.Invoke(Current);
        if (Current == 0) onDied?.Invoke();
    }

    public void Heal(int amount)
    {
        Current = Mathf.Min(maxHealth, Current + amount);
        onHealthChanged?.Invoke(Current);
    }
}

using UnityEngine;

// Spikes/enemies in 3D: deal damage on contact.
public class DamageOnTouch : MonoBehaviour
{
    [SerializeField] private int damage = 1;

    private void OnCollisionEnter(Collision collision)
    {
        if (collision.collider.TryGetComponent(out Health health)) health.TakeDamage(damage);
    }

    private void OnTriggerEnter(Collider other)
    {
        if (other.TryGetComponent(out Health health)) health.TakeDamage(damage);
    }
}

using UnityEngine;

// Coin/heart in 2D: Collider2D with "Is Trigger" on this object.
public class Pickup2D : MonoBehaviour
{
    [SerializeField] private int healAmount = 1;
    [SerializeField] private AudioClip sound;

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (!other.CompareTag("Player")) return;
        if (other.TryGetComponent(out Health health)) health.Heal(healAmount);
        if (sound != null) AudioSource.PlayClipAtPoint(sound, transform.position);
        Destroy(gameObject);
    }
}
